#include "birth_placement_settlement.hpp"
#include "movement_exact_detail.hpp"
#include <algorithm>
#include <limits>
namespace hanmo::resident {using namespace movement_detail;namespace {
void kind(BirthPlacementKind actual){if(actual!=BirthPlacementKind::settlement)throw Failure{common_failure("BirthPlacementOriginalCircumstanceProviderRequired",{},ErrorKind::unsupported_capability).error};}
void context(const SettlementBirthPlacementContext& x){if(&x.common!=&x.original_births.common||&x.catalog!=&x.original_births.common_catalog)fail("BirthSettlementSameCandidateRequired");}
ActorSpatialActualFactPrefix prefix(const CommonStore& c,std::size_t n){const auto& ids=c.state().facts.order();if(n>ids.size()||n>std::size_t(std::numeric_limits<Integer>::max()))fail("BirthSettlementOriginalCutOverflow");ActorSpatialActualFactPrefix out;out.common_fact_count=Integer(n);if(n){const auto* last=c.state().facts.find(ids[n-1]);if(!last)fail("BirthSettlementOriginalCutRequired");out.last_common_fact=SourceRef{last->domain,last->kind,last->id};}return out;}
std::size_t position(const CommonStore& c,const SourceRef& source){const auto* fact=c.state().facts.find(source.id);const auto& ids=c.state().facts.order();const auto at=std::find(ids.begin(),ids.end(),source.id);if(!fact||fact->id!=source.id||fact->domain!=source.domain||fact->kind!=source.kind||at==ids.end()||std::count(ids.begin(),ids.end(),source.id)!=1)fail("BirthSettlementOriginalSourceRequired",source.id);return std::size_t(at-ids.begin());}
const SettlementLocation& settlement(const Location& location){const auto* place=std::get_if<SettlementLocation>(&location);if(!place)throw Failure{common_failure("BirthPlacementOriginalCircumstanceProviderRequired",{},ErrorKind::unsupported_capability).error};return *place;}
BirthPlacement actual(const SettlementBirthPlacementContext& x,const StableId& delivery,const WorldMoment& at,const ActorSpatialActualFactPrefix& cut,const std::optional<SourceRef>& before){
 context(x);if(take(read_active_travel_dependent_binding(x.common,x.dependents,delivery,before,x.budget)))throw Failure{common_failure("BirthPlacementFollowingCarrierProviderRequired",delivery,ErrorKind::unsupported_capability).error};
 const auto point=take(read_actor_spatial_location_at_actual_fact_prefix(x.common,x.catalog,x.movement,x.carriers,x.registrations,x.foundation,x.actors,x.spatial,delivery,at,cut,x.military_handoffs,x.budget,&x.original_births.family_catalog,x.prior_births,x.military_actions));
 const auto& place=settlement(point.location_snapshot);const auto* locked=x.catalog.places.find(place.place_id);const auto* anchor=take(require_actor_ordinary_movement_anchor(point));const auto* original=std::get_if<OriginalMovementAnchor>(anchor);
 if(!locked||locked->settlement_id!=place.settlement_id||!original||point.actual_location_sources.size()!=1)fail("BirthSettlementOriginalLocationMismatch",delivery);
 const auto& original_place=settlement(original->location);const auto& head=point.actual_location_sources.front();if(original_place.place_id!=place.place_id||original_place.settlement_id!=place.settlement_id||head.schema<1||!source_valid(head.source))fail("BirthSettlementOriginalLocationMismatch",delivery);
 BirthPlacement result;result.location=point.location_snapshot;result.resolved_anchor=*anchor;result.placement_kind=BirthPlacementKind::settlement;result.placement_basis_ref={head.source,head.schema};return result;
}
void equal(const BirthPlacement& saved,const BirthPlacement& derived,ExactArithmeticBudget budget){kind(saved.placement_kind);const auto& a=settlement(saved.location);const auto& b=settlement(derived.location);const auto* old=std::get_if<OriginalMovementAnchor>(&saved.resolved_anchor);const auto* current=std::get_if<OriginalMovementAnchor>(&derived.resolved_anchor);if(saved.carrier_ref||saved.safe_boundary_ref||a.place_id!=b.place_id||a.settlement_id!=b.settlement_id||saved.placement_basis_ref.source_schema!=derived.placement_basis_ref.source_schema||!same_source(saved.placement_basis_ref.source_ref,derived.placement_basis_ref.source_ref)||!old||!current||!same_source(old->actual_source,current->actual_source)||!take(same_spatial_anchor(saved.resolved_anchor,derived.resolved_anchor,budget)))fail("BirthSettlementOriginalPlacementMismatch");}
void historical(const SettlementBirthPlacementContext& x,const BirthPlacementAdoption& adoption){
 context(x);kind(adoption.actual_placement.placement_kind);if(adoption.actual_birth_source.source_schema!=4||adoption.actual_birth_source.source_ref.domain!="family_birth"||adoption.actual_birth_source.source_ref.kind!="family_birth_recorded")fail("BirthSettlementOriginalBirth4Required");
 const auto source=take(read_born_character_source(x.original_births,{adoption.actual_birth_source.source_ref.id}));if(!source.birth||!source.accepted||!source.accepted->confirmation||source.birth->actor_id!=adoption.child_actor_id||source.birth->accepted_id!=adoption.birth_arrangement_id||source.accepted->confirmation->terms.gestating_actor_id!=adoption.delivery_actor_id||!same_moment(source.occurred_at,adoption.occurred_at,x.budget))fail("BirthSettlementOriginalBirthMismatch",adoption.child_actor_id);
 // The actual original Birth header precedes child creation and this S1 result.
 // It is the immutable cut, including any earlier same-M motion or handover.
 const auto cut=position(x.common,adoption.actual_birth_source.source_ref);equal(adoption.actual_placement,actual(x,adoption.delivery_actor_id,source.occurred_at,prefix(x.common,cut),adoption.actual_birth_source.source_ref),x.budget);
}
}
bool NativeSettlementBirthPlacementOriginalRead::bound_to(const CommonStore& c,const MovementExactState& m)const noexcept{return &c==&context_.common&&&m==&context_.movement&&&c==&context_.original_births.common&&&context_.catalog==&context_.original_births.common_catalog;}
Status NativeSettlementBirthPlacementOriginalRead::require_kind(BirthPlacementKind value)const{return status([&]{context(context_);kind(value);});}
Outcome<BirthPlacement> NativeSettlementBirthPlacementOriginalRead::read_actual(const BirthPlacementQuery& query)const{return guard<BirthPlacement>([&]{const auto& x=context_;context(x);const auto due=take(read_birth_placement_arrangement_at_due(x.original_births,query.delivery_actor_id,query.birth_arrangement_id,query.read_stamp,x.stamps,x.versions));const auto now=take(x.clock.read_current_moment());if(!same_moment(now,due.scheduled.occurrence,x.budget))fail("BirthSettlementDueMomentMismatch",query.birth_arrangement_id);
 const auto* delivery=x.common.actor(query.delivery_actor_id);if(!delivery||!delivery->alive)fail("BirthSettlementDeliveryActorRequired",query.delivery_actor_id);const auto& live=settlement(delivery->location);const auto* writer=x.movement.spatial_bindings.find("actor:"+query.delivery_actor_id);if(writer&&!std::holds_alternative<StableMovementWriter>(writer->writer))throw Failure{common_failure("BirthSettlementOriginalStablePlacementRequired",query.delivery_actor_id,ErrorKind::unsupported_capability).error};
 const auto result=actual(x,query.delivery_actor_id,now,prefix(x.common,x.common.state().facts.order().size()),{});const auto& proven=settlement(result.location);if(live.place_id!=proven.place_id||live.settlement_id!=proven.settlement_id)fail("BirthSettlementCurrentProjectionMismatch",query.delivery_actor_id);return result;
});}
Status NativeSettlementBirthPlacementOriginalRead::validate_at_actual_birth(const BirthPlacementAdoption& adoption)const{return status([&]{historical(context_,adoption);});}
Outcome<std::optional<MomentOwnerSource>> NativeSettlementBirthPlacementOriginalRead::read_actual_transport_source(const BirthPlacementAdoption& adoption)const{return guard<std::optional<MomentOwnerSource>>([&]{historical(context_,adoption);return std::optional<MomentOwnerSource>{};});}
Outcome<bool> NativeSettlementBirthPlacementOriginalRead::requires_dependent_binding(const BirthPlacementAdoption& adoption)const{return guard<bool>([&]{historical(context_,adoption);return false;});}
}
